#include <stdio.h>

int main() {
    int m[3][3] = {{2, 0, 1}, {4, 5, 6}, {7, 8, 9}};
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += m[i][i];
        if (i != 2 - i) {
            total += m[i][2 - i];
        }
    }
    printf("%d\n", total);
    return 0;
}
